<?php declare(strict_types=1); ?>
<style>
.fm{max-width:1250px;margin:auto;color:#172554}.fm .panel{background:#fff;border:1px solid #dfe5ef;border-radius:15px;padding:20px;margin:0 0 16px;box-shadow:0 3px 12px #10244a0a}.fm h2{margin:0 0 8px}.fm h3{margin:0 0 14px}.fm .filters{display:grid;grid-template-columns:2fr 1fr 1fr;gap:12px}.fm label{display:block;font-weight:700;font-size:13px;margin-bottom:6px}.fm input,.fm select{width:100%;padding:11px;border:1px solid #cbd5e1;border-radius:9px;box-sizing:border-box}.fm button,.fm .btn{display:inline-block;padding:10px 16px;border:0;border-radius:9px;background:#42349a;color:white;text-decoration:none;cursor:pointer}.fm .actions{margin-top:14px;display:flex;gap:10px}.fm .scroll{overflow-x:auto}.fm table{border-collapse:collapse;min-width:1600px;width:100%;font-size:13px}.fm th,.fm td{padding:11px 12px;border-bottom:1px solid #e2e8f0;text-align:left;white-space:nowrap}.fm th{background:#f3f6fb}.fm .muted{color:#64748b}.fm .pager{display:flex;align-items:center;gap:12px;margin-top:16px}.fm .status{font-weight:700}@media(max-width:700px){.fm .filters{grid-template-columns:1fr}}
