<div class="fm"><div class="panel"><h2>University Master Schedule</h2><p class="muted">Read-only university-wide course sections. Values and schedule status follow Admin's validation data.</p></div>
<div class="panel"><h3>Find Course Sections</h3><form method="get" action="master-schedule.php"><div class="filters"><div><label for="course">Course, ID, or CRN</label><input id="course" name="course" value="<?= e($filterCourse) ?>"></div><div><label for="semester">Semester</label><select id="semester" name="semester"><?php foreach($semesters as $term): ?><option value="<?= (int)$term['semester_ID'] ?>" <?= $semesterID===(int)$term['semester_ID']?'selected':'' ?>><?= e($term['semester_Name']) ?></option><?php endforeach; ?></select></div><div><label for="dept">Department</label><select id="dept" name="dept"><option value="">All departments</option><?php foreach($departments as $d): ?><option value="<?= (int)$d['dept_ID'] ?>" <?= $filterDepartment===(int)$d['dept_ID']?'selected':'' ?>><?= e($d['dept_Name']) ?></option><?php endforeach; ?></select></div></div><div class="actions"><button type="submit">Search</button><a class="btn" href="master-schedule.php">Clear</a></div></form></div>
<div class="panel"><h3>Course Sections</h3><p class="muted">Showing <?= count($pageRows) ?> of <?= (int)$totalRows ?> sections · Page <?= (int)$page ?> of <?= (int)$totalPages ?></p><div class="scroll"><table><thead><tr><th>CRN</th><th>Course ID</th><th>Credits</th><th>Course Name</th><th>Section ID</th><th>Instructor</th><th>Room</th><th>Days</th><th>Meeting Times</th><th>Minimum Seats</th><th>Seat Capacity</th><th>Actual Enrollment</th><th>Department</th><th>Mode</th><th>Status</th></tr></thead><tbody>
<?php foreach($pageRows as $r):
$errors=validate_schedule_row($r);
$start=$r['start_Time']??null;$end=$r['end_Time']??null;
$meeting=$start&&$end?date('g:i A',strtotime((string)$start)).' - '.date('g:i A',strtotime((string)$end)):'TBA';
$capacity=$r['capacity']??$r['SeatsCapacity']??$r['seats_Capacity']??null;
$dept=(string)($r['dept_Name']??$r['department_Name']??$r['dept_ID']??'—');
?><tr><td><?= e((string)$r['CRN']) ?></td><td><?= e((string)$r['course_ID']) ?></td><td><?= e((string)($r['course_Credits']??'—')) ?></td><td><?= e((string)$r['course_Name']) ?></td><td><?= e(str_pad((string)$r['section_No'],2,'0',STR_PAD_LEFT)) ?></td><td><?= e((string)$r['faculty_Name']) ?></td><td><?= e((string)($r['room_Label']??'Unassigned')) ?></td><td><?= e(implode(', ',array_map(static fn($d)=>substr((string)$d,0,3),$r['days']??[]))) ?></td><td><?= e($meeting) ?></td><td>10</td><td><?= $capacity===null?'—':e((string)$capacity) ?></td><td><?= e((string)$r['enrolled']) ?></td><td><?= e($dept) ?></td><td><?= e((string)($r['instruction_Mode']??'In-Person')) ?></td><td class="status"><?= $errors?'Attention':'Scheduled' ?></td></tr><?php endforeach; ?>
<?php if(!$pageRows): ?><tr><td colspan="15">No sections match the selected filters.</td></tr><?php endif; ?></tbody></table></div>
<?php if($totalPages>1): ?><nav class="pager"><?php if($page>1): ?><a class="btn" href="<?= e($pageUrl($page-1)) ?>">Previous</a><?php endif; ?><span>Page <?= (int)$page ?> of <?= (int)$totalPages ?></span><?php if($page<$totalPages): ?><a class="btn" href="<?= e($pageUrl($page+1)) ?>">Next</a><?php endif; ?></nav><?php endif; ?></div></div>
